from datetime import datetime, timezone

def parse_iso8601(s: str) -> datetime:
    try:
        if s.endswith('Z'):
            return datetime.fromisoformat(s[:-1]).replace(tzinfo=timezone.utc)
        elif '+' in s or '-' in s:
            return datetime.fromisoformat(s)
        else:
            return datetime.fromisoformat(s).replace(tzinfo=timezone.utc)
    except ValueError:
        raise ValueError("Unparseable ISO-8601 timestamp")

# Examples
# >>> parse_iso8601('2023-01-01T12:00:00Z')
# datetime.datetime(2023, 1, 1, 12, 0, tzinfo=datetime.timezone.utc)
# >>> parse_iso8601('2023-01-01T12:00:00+02:00')
# datetime.datetime(2023, 1, 1, 12, 0, tzinfo=datetime.timezone(datetime.timedelta(seconds=7200)))
# >>> parse_iso8601('2023-01-01T12:00:00-05:00')
# datetime.datetime(2023, 1, 1, 12, 0, tzinfo=datetime.timezone(datetime.timedelta(days=-1, seconds=7200)))
# >>> parse_iso8601('2023-01-01T12:00:00')
# datetime.datetime(2023, 1, 1, 12, 0, tzinfo=datetime.timezone.utc)
# >>> parse_iso8601('invalid-date')
# ValueError: Unparseable ISO-8601 timestamp
